INSERT INTO public.chemical_moa (active, scheme, group_code, group_name, ph_sensitive, time_of_day, note) VALUES ('GLYPHOSATE', 'herbicide', '9', 'EPSPS inhibitor', false, NULL, NULL);
INSERT INTO public.chemical_moa (active, scheme, group_code, group_name, ph_sensitive, time_of_day, note) VALUES ('GLUFOSINATE-AMMONIUM', 'herbicide', '10', 'Glutamine synthetase inhibitor', false, 'Spray it in the middle of the day. In the trial behind this, the same 140 g/ha gave 82 % control at midday and 65 % at dusk, and most plants sprayed at dusk were not controlled at all: glutamine synthetase is scarcer in the dark, and what survives the night rebuilds the enzyme.', 'Takano & Dayan 2021, Plants 10:2021.');
