INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('873525f6-ce0e-49c8-b5ff-dea0eb17ff3e', '4ca7d9ae-cb2a-4778-811e-c16e1f43e16a', 'Irrigation scheduling for canola in southern Alberta', 'Government of Alberta', 2011, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/5421624', 'https://open.alberta.ca/dataset/6b8e19b1-d8a8-4977-aa37-bd39c98bd5fc/resource/02987f0c-b714-4522-b3c2-31807c7787db/download/5421624-2011-agri-facts-irrigation-scheduling-canola-southern-alberta-149-561-1-2011-04.pdf', NULL, NULL, 3, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'Irrigation management is about controlling the rate, amount, and timing of applied irrigation water in a planned and efficient manner. With good irrigation management, a canola crop can have high yield and quality potential.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-15 02:32:13.389571+00', 'pending', NULL, NULL, NULL, NULL);
