INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('66fad5d9-6c85-49be-82ca-f103a6be6ade', '4ca7d9ae-cb2a-4778-811e-c16e1f43e16a', 'Irrigation scheduling for dry bean in southern Alberta', 'Government of Alberta', 2011, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/5333897-2011', 'https://open.alberta.ca/dataset/54d1f781-a716-4390-b09b-5f6155e3a665/resource/d72c97df-8d16-48ec-92d3-a32e1f0d40d0/download/5333897-2011-12-agri-facts-irrigation-scheduling-dry-bean-southern-alberta-revised-142-561-1.pdf', NULL, NULL, 4, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'Using good irrigation strategies with dry bean can mean a healthy crop with high yield and quality potential. In addition to ensuring that the dry bean crop is well-fertilized and well-protected from pests, growers are encouraged to properly manage irrigation by regularly monitoring soil water to ensure that the availability of water does not become a limiting factor in producing a high yielding dry bean crop.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-15 02:32:13.389571+00', 'pending', NULL, NULL, NULL, NULL);
