INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f8a664f5-b02c-40ed-aa20-6bdd7cfbfb1e', '4ca7d9ae-cb2a-4778-811e-c16e1f43e16a', 'Irrigation scheduling for sugar beet in southern Alberta (Revised February 2012)', 'Government of Alberta', 2012, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/5495143', 'https://open.alberta.ca/dataset/3c878668-7f17-4961-ac8e-89a14944cd5e/resource/d1bd6627-eec9-43ca-beee-55c08b800ccd/download/5495143-2012-agri-facts-irrigation-scheduling-sugar-beet-southern-alberta-revised-171-561-1.pdf', NULL, NULL, 4, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'Irrigation management is about controlling the rate, amount, and timing of applied irrigation water in a planned and efficient manner. With the best irrigation management practices, a sugar beet crop can achieve high root and sugar yield potential.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-15 02:32:13.389571+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0ae56da8-021d-4c4a-b1fd-e90c519c6ce2', '4ca7d9ae-cb2a-4778-811e-c16e1f43e16a', 'Irrigation scheduling for timothy-hay in southern Alberta', 'Government of Alberta', 2011, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/5421636', 'https://open.alberta.ca/dataset/1142bdb8-9ffe-4384-b3a7-08a1cfdb67e5/resource/609bb6ac-27fd-478e-b9e4-cfbbc41756c2/download/5421636-2011-agri-facts-irrigation-scheduling-timothy-hay-southern-alberta-127-561-1-2011-06.pdf', NULL, NULL, 4, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'Irrigation management is about controlling the rate, amount, and timing of applied irrigation water in a planned and efficient manner. With good irrigation management, a timothy hay crop can have high yield and quality potential.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-15 02:32:13.389571+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c2f086b9-d46c-45b7-8b7b-6f6d64e9e1ac', '4ca7d9ae-cb2a-4778-811e-c16e1f43e16a', 'Irrigation scheduling for winter wheat in southern Alberta', 'Government of Alberta', 2011, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/5332146', 'https://open.alberta.ca/dataset/a611fdcf-9188-42d0-9686-0cd28e8ffae7/resource/3caa08f5-7c29-42a4-9ce7-2c1266edb3fc/download/5332146-2011-agri-facts-irrigation-scheduling-winter-wheat-southern-ab-112-561-1.pdf', NULL, NULL, 4, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'Irrigation management is about controlling the rate, amount, and timing of applied irrigation water in a planned and efficient manner. With good irrigation management, a winter wheat crop can have high yield and quality potential.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-15 02:32:13.389571+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7bd8e93c-8de8-418c-91eb-e1b532c2245b', 'ac793dcc-9438-4a7b-b560-d450a979d7cd', 'Oldman River water conservation objective : Segment 4 : LNID weir to Rocky Coulee confluence', 'Government of Alberta', 2013, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/oldman-river-basin-water-conservation-objective-segment-4-lnid-weir-to-rocky-coulee', 'https://open.alberta.ca/dataset/87e05b42-8ab6-4d34-961c-c444357ab127/resource/107bb2c9-0a13-413d-a28b-d641e7d8be74/download/aep-wco-oldman-river-segment-4.pdf', NULL, NULL, 1, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'This schedule sets out the water conservation objective flows for the Oldman River from the Lethbridge Northern Irrigation District weir to the confluence of the Rocky Coulee. Water conservation objectives set out the volume and quality of water to remain in rivers for the protection of a natural water body and its aquatic environment. They are flow targets under the first-in-time, first-in-right priority water allocation system and apply to all new licences and existing licences with a retrofit provision.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-15 02:32:13.389571+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.crop_irrigation_sheets (id, coef_crop, coef_variant, crop_label, paper_id, agdex, published, season_mm_low, season_mm_high, peak_mm_day, peak_when, root_zone_cm, root_note, final_note, establish_note, created_at) VALUES ('4ce70868-c3a4-4637-90eb-4110a966a6b2', 'Barley', '', 'Barley', '1c128e26-a2af-4cc5-bfb4-390dcd3f07ac', '114/561-1', 'April 2011', 380, 430, 7.0, 'flowering and fruit formation', 100, 'More than 70 per cent of the season''s water comes from the upper 50 cm. Roots reach their full 100 cm at flowering.', 'Last refill at soft dough (between soft and hard dough on loamy sand). About 80 mm carries the crop from soft dough to maturity; none once the heads have turned brown.', NULL, '2026-11-15 02:32:13.436492+00');
INSERT INTO public.crop_irrigation_sheets (id, coef_crop, coef_variant, crop_label, paper_id, agdex, published, season_mm_low, season_mm_high, peak_mm_day, peak_when, root_zone_cm, root_note, final_note, establish_note, created_at) VALUES ('d9422ab6-7515-421c-be27-f89c350d91e4', 'Spring wheat', '', 'Spring wheat', 'bf0179e7-dc85-4ff7-ab26-0f86b792830b', '112/561-2', 'March 2011', 420, 480, 7.0, 'flowering and fruit formation', 100, 'More than 70 per cent of the season''s water comes from the upper 50 cm. Roots reach their full 100 cm at flowering.', 'Last refill at soft dough (between soft and hard dough on loamy sand). About 80 mm carries the crop from soft dough to maturity; none once the heads have turned brown.', NULL, '2026-11-15 02:32:13.436492+00');
INSERT INTO public.crop_irrigation_sheets (id, coef_crop, coef_variant, crop_label, paper_id, agdex, published, season_mm_low, season_mm_high, peak_mm_day, peak_when, root_zone_cm, root_note, final_note, establish_note, created_at) VALUES ('2fc31bf9-72af-404c-aa83-64dd8887e57a', 'Winter wheat', '', 'Winter wheat', 'c2f086b9-d46c-45b7-8b7b-6f6d64e9e1ac', '112/561-1', 'February 2011', 400, 430, 7.0, 'flowering and fruit formation', 100, 'More than 70 per cent of the season''s water comes from the upper 50 cm. Roots reach their full 100 cm at flowering.', 'Last refill at soft dough (between soft and hard dough on loamy sand). About 80 mm carries the crop from soft dough to maturity.', 'Seeded mid-September; the 0-30 cm seedbed should be near 80 per cent of field capacity at planting, with a 15 mm pass before seeding if it is dry. Peak use before freeze-up is only 1.5 to 2 mm a day in October.', '2026-11-15 02:32:13.436492+00');
INSERT INTO public.crop_irrigation_sheets (id, coef_crop, coef_variant, crop_label, paper_id, agdex, published, season_mm_low, season_mm_high, peak_mm_day, peak_when, root_zone_cm, root_note, final_note, establish_note, created_at) VALUES ('88960f72-11f4-4005-904e-29d8f4ed7b06', 'Canola', '', 'Canola', '873525f6-ce0e-49c8-b5ff-dea0eb17ff3e', '149/561-1', 'April 2011', 400, 480, 7.0, 'flowering and early pod development', 100, 'About 70 per cent of the season''s water comes from the upper 50 cm. Roots reach their full 100 cm at flowering.', 'Under disease-free conditions the last pass to refill the root zone comes when the earliest pods begin to ripen in August.', NULL, '2026-11-15 02:32:13.436492+00');
INSERT INTO public.crop_irrigation_sheets (id, coef_crop, coef_variant, crop_label, paper_id, agdex, published, season_mm_low, season_mm_high, peak_mm_day, peak_when, root_zone_cm, root_note, final_note, establish_note, created_at) VALUES ('71cc5e09-982e-44cb-8e11-b5b854203dae', 'Corn', 'silage', 'Silage corn', '384f6a4b-2c62-4db5-9e4d-f804f90e990f', '111/561-1', 'Revised August 2016', 500, 550, 7.0, 'mid-July, near the end of the vegetative stage', 100, 'More than 70 per cent of the season''s water comes from the upper 50 cm. Roots reach their full 100 cm at tasseling and silking.', 'Final refill between the dough and dent stages, a week to 10 days before harvest. Cut at 62 to 70 per cent whole-plant moisture, ideally 65.', NULL, '2026-11-15 02:32:13.436492+00');
INSERT INTO public.crop_irrigation_sheets (id, coef_crop, coef_variant, crop_label, paper_id, agdex, published, season_mm_low, season_mm_high, peak_mm_day, peak_when, root_zone_cm, root_note, final_note, establish_note, created_at) VALUES ('1cac1b3f-94c0-4a6b-8421-fadd05e93c71', 'Sugar beet', '', 'Sugar beet', 'f8a664f5-b02c-40ed-aa20-6bdd7cfbfb1e', '171/561-1', 'Revised February 2012', 500, 500, 8.0, 'the 30-day peak in July, at full canopy and taproot enlargement', 100, '70 per cent of the season''s water comes from the upper 50 cm. Roots reach their full 100 cm at full canopy closure and root enlargement.', 'A little water just before harvest keeps the soil slightly above 60 per cent, which makes digging easier.', NULL, '2026-11-15 02:32:13.436492+00');
INSERT INTO public.crop_irrigation_sheets (id, coef_crop, coef_variant, crop_label, paper_id, agdex, published, season_mm_low, season_mm_high, peak_mm_day, peak_when, root_zone_cm, root_note, final_note, establish_note, created_at) VALUES ('9ff3fb15-7bf4-44b3-9def-dfa0eb08ac63', 'Potato', '', 'Potato', '96f6c406-daf2-406e-b68e-6c1d1ee9c72e', '258/561-1', 'March 2011', 400, 550, 7.0, 'full flower and tuber bulking', 60, '70 per cent of the season''s water comes from the upper 30 cm of a 60 cm root zone.', 'When to stop depends on the end use and the variety: tuber size for some table varieties is regulated by holding soil water during bulking, so the last pass follows the size the market wants.', NULL, '2026-11-15 02:32:13.436492+00');
INSERT INTO public.crop_irrigation_sheets (id, coef_crop, coef_variant, crop_label, paper_id, agdex, published, season_mm_low, season_mm_high, peak_mm_day, peak_when, root_zone_cm, root_note, final_note, establish_note, created_at) VALUES ('4fd804a3-569a-45a3-962a-f32e2cd88723', 'Field peas', '', 'Pea', 'be53eff4-3a73-4693-965b-980f874ab260', '142/561-2', 'April 2011', 300, 370, 6.0, 'flowering and early pod development', 70, '70 per cent of the season''s water comes from the upper 35 cm of a 70 cm root zone.', 'Irrigation may stop when the pods start to ripen.', NULL, '2026-11-15 02:32:13.436492+00');
INSERT INTO public.crop_irrigation_sheets (id, coef_crop, coef_variant, crop_label, paper_id, agdex, published, season_mm_low, season_mm_high, peak_mm_day, peak_when, root_zone_cm, root_note, final_note, establish_note, created_at) VALUES ('47d9973c-bd6b-4ce1-8637-cd2542dd9d2a', 'Dry beans', '', 'Dry bean', '66fad5d9-6c85-49be-82ca-f103a6be6ade', '142/561-1', 'Revised December 2011', 300, 375, 7.0, 'flowering and early pod development', 60, 'Shallow-rooted: 85 per cent of the season''s water comes from the upper 40 cm of a 60 cm root zone.', 'Stop when at least 80 per cent of the pods show yellowing, or half the leaves on the plant are yellow.', NULL, '2026-11-15 02:32:13.436492+00');
INSERT INTO public.crop_irrigation_sheets (id, coef_crop, coef_variant, crop_label, paper_id, agdex, published, season_mm_low, season_mm_high, peak_mm_day, peak_when, root_zone_cm, root_note, final_note, establish_note, created_at) VALUES ('3c31ac09-08a0-4d37-932d-07ee3a6f711d', 'Alfalfa', 'per cut', 'Alfalfa hay', 'd7ddb069-db5d-4d30-8e98-c4117e2764f0', '121/561-1', 'July 2011', 540, 680, 9.0, 'early bloom in late June, for the first cut', 120, '40 per cent of the season''s water comes from the upper 30 cm, 70 per cent from the upper 60 and 90 per cent from the upper 90 of a 120 cm root zone -- only a tenth comes from below 90 cm, so watch the top 90.', 'Time the last pass before a cut so the soil is near 70 per cent at harvest, and the next within a week after cutting. About 100 to 125 mm of water per ton of hay.', 'Establishment year: hold the 0-30 cm above 60 per cent through the first 10 weeks with 15 mm passes. Withholding water to drive roots down is counterproductive -- early stress suppresses root growth more than shoot growth. Go into winter near 70 per cent; wetter than that raises winterkill.', '2026-11-15 02:32:13.436492+00');
INSERT INTO public.crop_irrigation_sheets (id, coef_crop, coef_variant, crop_label, paper_id, agdex, published, season_mm_low, season_mm_high, peak_mm_day, peak_when, root_zone_cm, root_note, final_note, establish_note, created_at) VALUES ('9e2b2f6c-2a3e-47a1-ba7e-97fcf2395e61', 'Timothy', '', 'Timothy hay', '0ae56da8-021d-4c4a-b1fd-e90c519c6ce2', '127/561-1', 'June 2011', 500, 550, 8.0, 'heading, late June to early July, for the first cut', 50, 'Nearly 70 per cent of the season''s water comes from the upper 25 to 30 cm of a 50 cm root zone.', 'The last pass goes on just after the second cut, filling the root zone to 100 per cent of available in early September.', 'Establishment year: hold the 0-30 cm above 60 per cent through emergence, early vegetative, tillering and boot, with 12 mm passes. The first cut takes 60 per cent of the season''s water (300-330 mm), the second the remaining 40 (200-220 mm).', '2026-11-15 02:32:13.436492+00');
