INSERT INTO public.crop_irrigation_refill (id, sheet_id, depth_cm, texture, taw_mm, refill_mm, depletion_pct) VALUES ('34c6817a-712d-40a9-88ea-56b54f890590', '9e2b2f6c-2a3e-47a1-ba7e-97fcf2395e61', 50, 'clay', 96, 39, 40.0);
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('df4256d6-261e-4d94-b70a-4b9eb35e25ff', '4ce70868-c3a4-4637-90eb-4110a966a6b2', 'ini', 1, 'Seedbed and emergence', 50, NULL, 60.0, 'The 0-50 cm should be above 60 per cent at planting. Seeded dry in late April, give light 15 mm passes as soon as water is available to stop the surface crusting.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('60af06d4-f3cc-4925-a964-9c0754e2f534', '4ce70868-c3a4-4637-90eb-4110a966a6b2', 'dev', 2, 'Tillering to late boot', 50, 65.0, 60.0, 'Start near 65 per cent so it never falls below 60. Light and frequent, while building the 50-100 cm zone towards field capacity for flowering.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('3a251258-dbbe-4bfd-a07c-99be6d824fe9', '4ce70868-c3a4-4637-90eb-4110a966a6b2', 'mid', 3, 'Early heading to fruit formation', 100, 60.0, 60.0, 'Step the reading depth to 100 cm at early heading. Fill the whole 100 cm to field capacity at late boot whether or not the trigger has been reached -- that keeps the canopy dry through flowering, when fusarium head blight strikes. Next pass about 10 days after first flower.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('d00263f4-dfad-48ed-ac76-edef3e20ccea', '4ce70868-c3a4-4637-90eb-4110a966a6b2', 'late', 4, 'Soft dough to maturity', 100, NULL, 60.0, 'About 80 mm of water carries barley from soft dough to physiologic maturity.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('d155391d-b754-4ae1-be29-8428a4df0901', 'd9422ab6-7515-421c-be27-f89c350d91e4', 'ini', 1, 'Seedbed and emergence', 50, NULL, 60.0, 'The 0-50 cm should be above 60 per cent at planting. Seeded dry in late April, give light 15 mm passes as soon as water is available.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('acefb71d-a059-4b52-8df8-e56add3eb42b', 'd9422ab6-7515-421c-be27-f89c350d91e4', 'dev', 2, 'Tillering to late boot', 50, 65.0, 60.0, 'Start near 65 per cent so it never falls below 60, and build the 50-100 cm zone towards field capacity for flowering.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('a0f042ad-10f6-460c-8bad-c924cf96df00', 'd9422ab6-7515-421c-be27-f89c350d91e4', 'mid', 3, 'Early heading to fruit formation', 100, 60.0, 60.0, 'Step the reading depth to 100 cm at late boot to early heading, and fill the whole zone to field capacity then whether or not the trigger has been reached -- fusarium head blight follows a wet canopy at flowering. Next pass about 10 days after first flower.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('53762593-1fed-47c7-8885-d823cdb0ed8d', 'd9422ab6-7515-421c-be27-f89c350d91e4', 'late', 4, 'Soft dough to maturity', 100, NULL, 60.0, 'About 80 mm of water carries spring wheat from soft dough to physiologic maturity.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('f2c98214-dc3a-4be0-ba22-2a259004c774', '2fc31bf9-72af-404c-aa83-64dd8887e57a', 'ini', 1, 'Seeding to freeze-up', 30, NULL, 60.0, 'Irrigate before seeding rather than after: the seedbed wants to be near 80 per cent of field capacity, and a pass on a seeded field crusts it.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('c4d63e9b-8ef9-4560-9dd6-74f70aeca917', '2fc31bf9-72af-404c-aa83-64dd8887e57a', 'dev', 2, 'Tillering to late boot', 50, 60.0, 50.0, 'Winter wheat is the one crop Alberta lets run to 50 per cent before heading -- start near 60. Its shallow refill table is quoted at 50 per cent depletion for that reason.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('0a0bf3df-9695-4919-8840-f8acade8ec83', '2fc31bf9-72af-404c-aa83-64dd8887e57a', 'mid', 3, 'Early heading to fruit formation', 100, 60.0, 60.0, 'From early heading the floor rises to 60 per cent over the full 100 cm. Fill the whole zone at late boot to early heading whether or not the trigger has been reached, to keep the canopy dry through flowering (fusarium head blight).');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('b0fe6113-0796-4aef-b8ef-d6f4398fc94e', '2fc31bf9-72af-404c-aa83-64dd8887e57a', 'late', 4, 'Soft dough to maturity', 100, NULL, 60.0, 'About 80 mm of water carries winter wheat from soft dough to physiologic maturity.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('83435fb0-457d-476b-99fd-68160aa0ca15', '88960f72-11f4-4005-904e-29d8f4ed7b06', 'ini', 1, 'Seedbed and emergence', 50, NULL, 60.0, 'The 0-50 cm should be above 60 per cent at planting. Seeded into moist soil, do not irrigate before emergence -- the crust costs plants.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('238f6bc4-ba85-49a2-90bc-81dddb89968f', '88960f72-11f4-4005-904e-29d8f4ed7b06', 'dev', 2, 'Seedling, rosette and elongation', 50, NULL, 60.0, 'Keep the upper 50 cm above 60 per cent and build the 50-100 cm zone towards field capacity for flowering.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('bd4fd3c6-61fa-4a60-af69-2cf98b3786e3', '88960f72-11f4-4005-904e-29d8f4ed7b06', 'mid', 3, 'Flowering and pod set', 100, NULL, 60.0, 'Step the reading depth to 100 cm at flowering: fewer, larger passes keep the canopy dry, which discourages sclerotinia. Flowering lasts about 30 days and is where water stress costs the most yield. Fungicide at 20 to 30 per cent bloom; stop irrigating if sclerotinia is severe.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('b711915e-eb44-4ac8-b60c-a96d32144418', '88960f72-11f4-4005-904e-29d8f4ed7b06', 'late', 4, 'Pod development and ripening', 100, NULL, 60.0, 'Depletion below 60 per cent at any stage costs seed yield and oil content.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('4f5aa76b-f98c-4961-a207-512d4cd7ed62', '71cc5e09-982e-44cb-8e11-b5b854203dae', 'ini', 1, 'Seedbed and emergence', 50, NULL, 60.0, 'Seed into soil warmer than 10 degrees with the 0-50 cm above 60 per cent. Seeded dry in early May, light 15 mm passes as soon as water is available.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('a7707ddc-e652-4eea-9698-39ac2f18b344', '71cc5e09-982e-44cb-8e11-b5b854203dae', 'dev', 2, 'Leaf production (pre-tasseling)', 50, 65.0, 60.0, 'Start near 65 per cent so the upper 50 cm never falls below 60, and build the 50-100 cm zone for the late-June to mid-August peak.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('32be49d0-ddc4-479e-837a-51400651427a', '71cc5e09-982e-44cb-8e11-b5b854203dae', 'mid', 3, 'Tasseling and silking', 50, 65.0, 60.0, 'The reading depth stays at 50 cm through silking. This is where stress hurts most: dry silks and pollen mean poor pollination and barren ear tips.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('79d20fd6-1ff9-4575-9e0e-cd766d91a78b', '71cc5e09-982e-44cb-8e11-b5b854203dae', 'late', 4, 'Blister kernel to dent', 100, NULL, 60.0, 'Step the reading depth to 100 cm at blister kernel -- fewer, larger passes from there on.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('0c76e68f-faef-466e-884e-569bbe096005', '1cac1b3f-94c0-4a6b-8421-fadd05e93c71', 'ini', 1, 'Seedbed and emergence', 50, NULL, 60.0, 'Best is a 0-50 cm near 80 per cent at planting -- the seed goes in 2.5 cm deep, so a dry surface costs the stand. Seeded dry in late April, light 15 mm passes from early May.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('3787b3c6-5d0b-4cec-8158-9ad6e3d94e83', '1cac1b3f-94c0-4a6b-8421-fadd05e93c71', 'dev', 2, 'Emergence to canopy closure (16-leaf)', 50, 65.0, 60.0, 'Keep the upper 50 cm above 60 per cent and the crop closes canopy early. Build the 50-100 cm zone for the July peak.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('fad25df3-c528-4044-be96-c4037086adc7', '1cac1b3f-94c0-4a6b-8421-fadd05e93c71', 'mid', 3, 'Full canopy closure and root enlargement', 100, 65.0, 60.0, 'Step the reading depth to 100 cm at full canopy closure: fewer, larger passes, reaching the mature roots.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('5de42c1d-e4a2-41d9-acf9-7d864425221d', '1cac1b3f-94c0-4a6b-8421-fadd05e93c71', 'late', 4, 'Leaf die-back to harvest', 100, 65.0, 60.0, 'Demand falls as the old leaves die and the weather cools.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('0d8443b5-da94-4e44-b4a5-63e4adcf5240', '9ff3fb15-7bf4-44b3-9def-dfa0eb08ac63', 'ini', 1, 'Planting to emergence', 30, NULL, 65.0, 'Do not irrigate between planting and emergence: a wet seed piece invites soil disease organisms.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('378a7a93-507e-4d04-9795-11e9c6bf86b7', '9ff3fb15-7bf4-44b3-9def-dfa0eb08ac63', 'dev', 2, 'Tuber initiation', 30, 70.0, 70.0, 'The one stage with a 70 per cent floor rather than 65. Potato is most sensitive to stress here, and starting at 70 raises the number of tubers per plant. Reservoir tillage (dammer dyking) evens the water out across the field.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('4732a1b4-b9c7-4419-9dac-ed58b2c6b11b', '9ff3fb15-7bf4-44b3-9def-dfa0eb08ac63', 'mid', 3, 'Tuber bulking', 60, 65.0, 65.0, 'Hold between 65 and 100 per cent. Outside that band costs marketable yield and brings hollow heart, knobbiness and cracks.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('c5811a4f-7306-4377-b8cf-fea742f4c108', '9ff3fb15-7bf4-44b3-9def-dfa0eb08ac63', 'late', 4, 'Maturation and harvest', 60, 65.0, 65.0, 'Keep near 65 per cent for digging -- drier than that and the tubers bruise.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('c04f06aa-6820-4d14-9ee5-67334b3ee4c2', '4fd804a3-569a-45a3-962a-f32e2cd88723', 'ini', 1, 'Seedbed and emergence', 40, NULL, 60.0, 'The 0-40 cm should be above 60 per cent at planting. Seed early so the crop flowers before the summer heat.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('779351c8-b956-4549-a4eb-16e42168f298', '4fd804a3-569a-45a3-962a-f32e2cd88723', 'dev', 2, 'Vegetative', 40, NULL, 60.0, 'Manage the 40 cm zone -- light and frequent -- while building the 40-70 cm zone towards field capacity for flowering.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('538b031a-0ed4-4815-a94f-39b73c0faf7d', '4fd804a3-569a-45a3-962a-f32e2cd88723', 'mid', 3, 'Flowering and pod set', 70, NULL, 60.0, 'Step the reading depth from 40 to 70 cm at first flower. Stress here aborts flowers and pods; water now sets the number of pods and seeds per pod.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('9af4f16d-90a2-4434-bf9a-9956a23d32da', '4fd804a3-569a-45a3-962a-f32e2cd88723', 'late', 4, 'Pod development and pod fill', 70, NULL, 60.0, 'Water at pod development puts weight into the pods and seeds. Fewer, larger passes keep the soil surface dry, which discourages fungal disease.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('6f467232-00c7-440e-8eb0-43a865b47736', '47d9973c-bd6b-4ce1-8637-cd2542dd9d2a', 'ini', 1, 'Seedbed and emergence', 30, NULL, 60.0, 'Best is a 0-60 cm profile near field capacity at planting. If the top 10 cm is dry, a 15 mm pass BEFORE seeding; never just after, which crusts the soil and costs plants.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('30186306-1628-42c0-ab9b-e86e3f3cdf91', '47d9973c-bd6b-4ce1-8637-cd2542dd9d2a', 'dev', 2, 'Vegetative (pre-flowering)', 30, NULL, 60.0, 'Manage the 30 cm zone, not the 60 -- light and frequent passes close the canopy faster and mature the crop earlier. Build the 30-60 cm zone for flowering.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('48a8980b-7d26-401c-8551-f5e4c367a3dc', '47d9973c-bd6b-4ce1-8637-cd2542dd9d2a', 'mid', 3, 'Flowering and pod set', 60, NULL, 60.0, 'Step the reading depth from 30 to 60 cm at flowering. Stress here aborts flowers and pods.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('2a7c9947-3066-4151-a7ef-010220fca325', '47d9973c-bd6b-4ce1-8637-cd2542dd9d2a', 'late', 4, 'Pod fill and maturation', 60, NULL, 60.0, 'Fill the whole 60 cm zone at the start of pod fill so the crop needs few passes through the white-mould window. If mould weather sets in (cloudy and humid), soil water may go to near 50 per cent during pod fill without a significant yield loss.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('b950732b-8a18-4709-9fa1-5f44b48bbd9e', '3c31ac09-08a0-4d37-932d-07ee3a6f711d', 'ini', 1, 'Regrowth after cutting', 120, NULL, 60.0, 'A full pass goes on immediately after the first and second cut -- water to the roots is what lets the stand recover from defoliation.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('81530ed9-d731-497a-b052-a28a60ffd41c', '3c31ac09-08a0-4d37-932d-07ee3a6f711d', 'dev', 2, 'Vegetative', 120, NULL, 60.0, 'Keep the 120 cm zone above 60 per cent. Peak use is nearly 9 mm a day for the first cut, 8 for the second, 7 for the third.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('9571415a-ba6f-4ff8-a54c-68e2ce8e5dc1', '3c31ac09-08a0-4d37-932d-07ee3a6f711d', 'mid', 3, 'Bud to early bloom', 120, NULL, 60.0, 'Fill the whole root zone to 100 per cent of available, especially through a hot, dry July.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('63d72caf-f634-4d26-8329-813b0a6f2be7', '3c31ac09-08a0-4d37-932d-07ee3a6f711d', 'late', 4, 'Cutting and after', 120, NULL, 60.0, 'Aim for about 70 per cent at harvest, and again when the third cut is off after the first killing frost -- the taproots are storing carbohydrates for winter and spring.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('dcb70b04-ae4a-465c-a2b2-7e985af6c0b3', '9e2b2f6c-2a3e-47a1-ba7e-97fcf2395e61', 'ini', 1, 'Emergence and regrowth', 30, NULL, 60.0, 'Hold the 0-30 cm above 60 per cent. Light 12 mm passes recharge that zone without runoff.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('fea48857-6cfd-452e-b664-bbd49762dc49', '9e2b2f6c-2a3e-47a1-ba7e-97fcf2395e61', 'dev', 2, 'Tillering to boot', 30, 65.0, 60.0, 'Start near 65 per cent so the 30 cm zone never falls below 60.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('b985e36b-ab5b-4dac-b1ff-19f939faa949', '9e2b2f6c-2a3e-47a1-ba7e-97fcf2395e61', 'mid', 3, 'Full head and flowering', 50, 65.0, 60.0, 'Step the reading depth from 30 to 50 cm at the full head stage, and fill the 0-50 cm to field capacity at early heading. Peak use is nearly 8 mm a day for the first cut and 6 for the second.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('6198e4fd-46f1-486f-bb27-01e102336dfb', '9e2b2f6c-2a3e-47a1-ba7e-97fcf2395e61', 'late', 4, 'After cutting', 50, 65.0, 60.0, 'A full pass goes on right after the first cut in early July, with about 60 per cent of the spring nitrogen rate, and again after the second cut.');
