INSERT INTO public.crop_succession_rules (id, prev_crop_id, next_crop_id, created_at, preference, notes, source) VALUES ('8ba21a6b-2dd4-4560-a4f3-3ffbcfd061f0', 'd4ffecc8-fd06-472c-ab03-ca9d921a1c5c', '2bc08ccd-a42e-4d40-88ed-611274ed5d97', '2026-11-15 02:31:52.979643+00', 'recommended', 'Cereal before potatoes is the standard southern Alberta rotation: breaks Rhizoctonia and scab, residue on the sands.', 'suggested');
INSERT INTO public.crop_succession_rules (id, prev_crop_id, next_crop_id, created_at, preference, notes, source) VALUES ('225bfc82-ae19-4f90-93c6-7edd917a6dfb', '522e7188-0c23-49b8-bd6b-184cdf0d6109', '97bf6aae-4080-436f-b172-604b819fe7ab', '2026-11-15 02:31:52.979643+00', 'no_go', 'Forage legume straight after forage legume: same weevils, root rots and autotoxic residue — put a cereal between.', 'suggested');
