INSERT INTO public.crop_succession_rules (id, prev_crop_id, next_crop_id, created_at, preference, notes, source) VALUES ('57c992f3-863d-4209-a27b-0da16aa4ad72', 'fb7c4a64-8924-45d8-a0aa-af0731da760c', '522e7188-0c23-49b8-bd6b-184cdf0d6109', '2026-11-15 02:31:52.979643+00', 'caution', 'Both host white mould and Fusarium/Rhizoctonia root rots, and the alfalfa gains nothing from the bean N — a cereal between is better.', 'suggested');
