INSERT INTO public.crop_succession_rules (id, prev_crop_id, next_crop_id, created_at, preference, notes, source) VALUES ('97c065e6-e10f-40d7-9fed-84fb742dce99', 'a572e2cb-4fcb-4d83-805d-8eea702e0ede', '522e7188-0c23-49b8-bd6b-184cdf0d6109', '2026-11-15 02:31:52.979643+00', 'possible', 'Canola stubble takes alfalfa well; both host sclerotinia, and volunteer canola in the new stand needs a plan.', 'suggested');
